INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 45 anos, hipertenso e sedentário, apresenta dor torácica que irradia para a mandíbula durante esforço físico. Ele toma atenolol 50 mg/dia. O teste ergométrico é interrompido por dor torácica típica e infra de ST de 2 mm em V4-V6 no final do segundo estágio do protocolo de Bruce. Qual a classificação funcional da angina deste paciente, segundo a Canadian Cardiovascular Society (CCS)?", "options": {"a": "CCS I.", "b": "CCS II.", "c": "CCS III.", "d": "CCS IV.", "e": "CCS V."}, "answer": "b", "rationale": "CCS II: Limitação leve da atividade habitual (angina em caminhadas rápidas, subida de escadas, caminhada > 2 quarteirões). CCS I é apenas em esforços extenuantes; CCS III em esforços mínimos; CCS IV em repouso.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Esforço moderado (Bruce estagio 2).", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "CCS", "Angina", "Classificação"]}', 86, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente com angina instável revela uma lesão excêntrica com bordos irregulares e imagem sugestiva de trombo intracoronário (lesão tipo C da AHA/ACC). Qual a conduta de antiagregação potente (inibidor da GP IIb/IIIa) recomendada DURANTE o procedimento se houver grande carga trombótica ou fenômeno de no-reflow?", "options": {"a": "Aspirina oral extra.", "b": "Tirofiban ou Eptifibatide venoso.", "c": "Dose extra de heparina.", "d": "Troca de stent por balão.", "e": "Varfarina imediata."}, "answer": "b", "rationale": "Inibidores da GP IIb/IIIa (Tirofiban) são indicados em situações de resgate durante a ICP, especialmente em casos de alta carga trombótica ou complicações trombóticas agudas do perprocedimento.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Antiagregação de resgate potente.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Farmacologia", "SCA", "Invasivo"]}', 87, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 70 anos, diabética, admitida com náuseas, vômitos e tontura. O ECG revela um Bloqueio Atrioventricular Total (BAVT) com escape ventricular de 30 bpm. A troponina está positiva. Qual o vaso culpado mais provável e qual o território do infarto?", "options": {"a": "Artéria Descendente Anterior; Infarto Anterior.", "b": "Artéria Coronária Direita; Infarto Inferior.", "c": "Artéria Circunflexa; Infarto Lateral Altp.", "d": "Artéria Diagonal; Infarto de Parede Lateral.", "e": "Tronco de Coronária Esquerda."}, "answer": "b", "rationale": "O infarto inferior (ACD) é frequentemente associado a bradiarritmias por isquemia do nó AV (irrigado pela ACD em 90% das pessoas) ou reflexo vagal. Náuseas e vômitos também são sintomas reflexos comuns no infarto inferior.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Correlação anatômico-clínica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "ECG", "IAM", "BAVT"]}', 88, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal vantagem do Ticagrelor em relação ao Clopidogrel no tratamento da SCA sem supra de ST, conforme demonstrado no estudo PLATO?", "options": {"a": "É mais barato.", "b": "É um inibidor reversível e não requer ativação hepática pelo citocromo P450 (ação direta), proporcionando inibição plaquetária mais rápida e consistente.", "c": "Não causa falta de ar.", "d": "Pode ser usado com varfarina sem risco.", "e": "Basta uma dose por semana."}, "answer": "b", "rationale": "O Ticagrelor venceu o Clopidogrel no PLATO principalmente pela sua potência e previsibilidade farmacológica. Sendo um inibidor direto e reversível, ele age mais rápido e de forma independente de variantes genéticas que afetam a ativação do clopidogrel (como polimorfismos CYP2C19).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diferencial farmacológico chave.", "c": "Incorreta. Ticagrelor causa dispneia em ~15% dos casos (efeito da adenosina).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Farmacologia", "Ticagrelor", "SCA"]}', 89, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A presença de onda Q patológica no ECG sugere:", "options": {"a": "Isquemia reversível.", "b": "Área de necrose miocárdica (cicatriz) antiga ou infarto transmural estabelecido.", "c": "Espasmo coronariano.", "d": "Sobrecarga de volume.", "e": "Efeito colateral de medicação."}, "answer": "b", "rationale": "A onda Q (com duração >= 0,04s e amplitude > 25% da onda R seguinte) representa a perda de vetores de despolarização naquela parede, geralmente indicando cicatriz fibrótica pós-infarto.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Significado eletrofisológico da onda Q.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "ECG", "Ondas Q", "Necrose"]}', 90, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente com dor torácica típica iniciada há 6 horas. ECG mostra supra de ST em V1-V6. O hospital dispõe de hemodinâmica, mas a sala está ocupada por outra emergência e o tempo previsto de espera é de 3 horas. Qual a conduta correta?", "options": {"a": "Aguardar as 3 horas para realizar a ICP primária.", "b": "Realizar fibrinólise química imediatamente (se não houver contraindicação) devido ao atraso previsto para ICP.", "c": "Transferir para outro hospital a 4 horas de distância.", "d": "Dar apenas aspirina e observar.", "e": "Dar nitrato e aguardar a sala."}, "answer": "b", "rationale": "O tempo é miocárdio. Se o atraso previsto para a ICP primária exceder 120 minutos (2 horas) em relação ao tempo em que a fibrinólise poderia ser feita, deve-se optar pela fibrinólise.", "option_rationales": {"a": "Incorreta. Atraso excessivo compromete o músculo.", "b": "Correta. Regra dos 120 minutos para escolha da reperfusão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Diretrizes", "SCA", "Tempo-Dependente"]}', 91, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual dos seguintes exames é o mais adequado para avaliar a anatomia coronariana e excluir doença aterosclerótica em um paciente de 40 anos, com dor torácica atípica e probabilidade pré-teste baixa/intermediária?", "options": {"a": "Cineangiocoronariografia invasiva.", "b": "Angiotomografia de Coronárias (Angio-TC).", "c": "Ecocardiograma transesofágico.", "d": "Holter de 24h.", "e": "Ressonância magnética sem contraste."}, "answer": "b", "rationale": "A Angio-TC tem um excelente valor preditivo negativo. Em pacientes de baixo/moderado risco, um exame normal permite excluir doença coronariana sem a necessidade de procedimentos invasivos (cateterismo).", "option_rationales": {"a": "Incorreta. Muito invasivo para baixa probabilidade.", "b": "Correta. Exame de escolha para triagem anatomica não invasiva.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Angio-TC", "Diagnóstico", "SCA"]}', 92, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A meta de pressão arterial recomendada para um paciente pós-infarto com hipertensão e diabetes, segundo as diretrizes brasileiras de hipertensão de 2020, visando proteção cardiovascular máxima é:", "options": {"a": "< 150/90 mmHg.", "b": "< 140/90 mmHg.", "c": "< 130/80 mmHg.", "d": "< 110/60 mmHg.", "e": "Apenas reduzir a pressão sistólica em 10%."}, "answer": "c", "rationale": "Pacientes de alto risco cardiovascular (pós-SCA, diabéticos, etc) devem buscar metas mais agressivas (BP < 130/80 mmHg), desde que tolerado.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Meta para baixo risco.", "c": "Correta. Meta para alto risco/diabéticos.", "d": "Incorreta. Risco de hipotensão e roubo coronário (curva em J).", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "HAS", "Metas", "Diabetes"]}', 93, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 24 anos, apresenta síncope durante jogo de futebol. O ECG mostra supra de ST descendente tipo ''sela de cavalo'' em V1 e V2. Qual a principal suspeita de canalopatia que pode levar a morte súbita e qual o medicamento que deve ser evitado?", "options": {"a": "Síndrome de Lown-Ganong-Levine; evitar aspirina.", "b": "Síndrome de Brugada; evitar antiarrítmicos da classe Ic (ex: propafenona, flecainida).", "c": "Síndrome do QT Longo; evitar potássio.", "d": "WPW; evitar verapamil.", "e": "Takotsubo; evitar adrenalina."}, "answer": "b", "rationale": "O padrão de Brugada tipo 2 ou 3 (sela de cavalo) ou tipo 1 (coved) é marcador de risco para FV. Bloqueadores de canais de sódio (Classe Ic) podem desencadear ou exacerbar o fenótipo e causar arritmias fatais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico diferencial importante em síncope do jovem.", "c": "Incorreta. QT longo precisa de potássio alto.", "d": "Incorreta. Verapamil deve ser evitado se houver FA pré-excitada, mas o ECG descreveu Brugada.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Arritmias", "Brugada", "Morte Súbita"]}', 94, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No tratamento do infarto inferior, qual o sinal clínico ao exame físico que MAIS sugere a necessidade de evitar nitratos e diuréticos?", "options": {"a": "Presença de B4.", "b": "Fervores em bases pulmonares.", "c": "Hipotensão associada a campos pulmonares limpos.", "d": "Sopro sistólico no foco aórtico.", "e": "Edema de membros inferiores."}, "answer": "c", "rationale": "Campos pulmonares limpos sugerem que não há falência do VE. A hipotensão no infarto inferior aponta fortemente para infarto de VD, onde o volume é essencial.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Sugere falência de VE.", "c": "Correta. Diagnóstico clínico de infarto de VD.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Infarto de VD", "Manejo", "SCA"]}', 95, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma artéria descendente anterior que nasce da artéria coronária direita e passa ENTRE a aorta e a artéria pulmonar. Qual o risco clínico desta anomalia congênita?", "options": {"a": "Nenhum, é uma variante benigna.", "b": "Risco de compressão durante o exercício, causando isquemia súbita e morte.", "c": "Risco de infecção valvular.", "d": "Ruptura da aorta.", "e": "Fibrose pulmonar."}, "answer": "b", "rationale": "Trajetos interarteriais de coronárias anômalas (malignant course) podem sofrer compressão extrínseca durante estados de alto débito e vasodilatação da aorta/pulmonar (exercício), levando a morte súbita em atletas jovens.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Anomalia coronariana de alto risco.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Anomalia Coronária", "Morte Súbita", "Exercício"]}', 96, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a dose de manutenção padrão do Clopidogrel para prevenção de trombose de stent após uma SCA?", "options": {"a": "300 mg/dia.", "b": "150 mg/dia.", "c": "75 mg/dia.", "d": "100 mg/dia.", "e": "25 mg/dia."}, "answer": "c", "rationale": "Após a dose de ataque (300-600 mg), a manutenção é feita with 75 mg uma vez ao dia.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Clopidogrel", "SCA"]}', 97, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 55 anos, obeso, tabagista, apresenta angina estável. A cineangiocoronariografia revela lesões de 50-60% em múltiplos vasos. O médico decide realizar um Ultrassom Intracoronário (IVUS). Qual parâmetro derivado do IVUS ajuda a decidir se uma lesão na descendente anterior é crítica (excluindo tronco)?", "options": {"a": "Área de secção transversa do lúmen < 4 mm2.", "b": "Comprimento da lesão > 100 mm.", "c": "Presença de gordura perivascular.", "d": "Velocidade do sangue.", "e": "Número de placas."}, "answer": "a", "rationale": "Embora o FFR seja o padrão-ouro funcional, o IVUS utiliza a área luminal mínima (MLA). No tronco de esquerda, MLA < 6 mm2 é o corte; em vasos maiores como a DA proximal, MLA < 4 mm2 costuma ser considerado significante em alguns consensos.", "option_rationales": {"a": "Correta. Parâmetro anatômico do IVUS.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "IVUS", "Hemodinâmica", "SCA"]}', 98, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A síndrome de Kounis descreve uma síndrome coronariana aguda desencadeada por:", "options": {"a": "Ansiedade extrema.", "b": "Reação inflamatória alérgica ou anafilática (mediada por mastócitos e histamina).", "c": "Hipotermia acentuada.", "d": "Exercício de alta intensidade.", "e": "Uso de estatinas."}, "answer": "b", "rationale": "A síndrome de Kounis é a ''angina alérgica'', onde mediadores inflamatórios da anafilaxia causam vasoespasmo coronário ou ruptura de placa.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Entidade clínica específica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "Kounis", "Alergia", "SCA"]}', 99, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente idoso, 85 anos, admitido com IAMssST, evoluindo com confusão mental e bradicardia sinusal de 45 bpm. Qual o betabloqueador de escolha para controle de sintomas adrenérgicos pós-infarto que apresenta menor atravessamento da barreira hematoencefálica e menor efeito no SNC?", "options": {"a": "Propranolol.", "b": "Metoprolol.", "c": "Atenolol.", "d": "Carvedilol.", "e": "Esmolol."}, "answer": "c", "rationale": "O Atenolol é um betabloqueador hidrofílico, o que reduz sua penetração no SNC e, consequentemente, causa menos pesadelos e sintomas psiquiátricos/confusionais do que os lipofílicos (como propranolol e metoprolol). No entanto, betabloqueadores devem ser evitados na bradicardia.", "option_rationales": {"a": "Incorreta. Muito lipofílico.", "b": "Incorreta. Lipofílico.", "c": "Correta. Propriedade farmacocinética diferencial.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Farmacologia", "Betabloqueador", "SNC"]}', 100, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal indicação para o uso de cilostazol em um paciente com coronariopatia crônica e doença arterial obstrutiva periférica (DAOP)?", "options": {"a": "Melhorar a insuficiência cardíaca.", "b": "Reduzir a distância de claudicação intermitente (melhora funcional da DAOP).", "c": "Dissolver trombos coronários.", "d": "Substituir a aspirina.", "e": "Diminuir o colesterol."}, "answer": "b", "rationale": "O Cilostazol é um inibidor da fosfodiesterase III com propriedades vasodilatadoras periféricas e antiagregantes, sendo aprovado para o tratamento dos sintomas de claudicação na DAOP.", "option_rationales": {"a": "Incorreta. Contraindicado na IC grave.", "b": "Correta. Indicação principal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Vascular", "DAOP", "Claudicação"]}', 101, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A oclusão da artéria descendente posterior (DP) e dos ramos posterolaterais (PL) causa infarto em qual região do ventrículo esquerdo?", "options": {"a": "Parede Anterior.", "b": "Parede Inferior e Infero-lateral.", "c": "Parede Lateral Alta.", "d": "Septo Superior.", "e": "Apenas Átrio Direito."}, "answer": "b", "rationale": "A DP e PL irrigam a face diafragmática do coração.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Anatomia coronariana aplicada.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Anatomia", "IAM", "Vascular"]}', 102, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No tratamento de um paciente com choque cardiogênico pós-infarto, qual a droga inotrópica que age via inibição da fosfodiesterase III, aumentando o cAMP intracelular de forma independente do receptor beta?", "options": {"a": "Dopamina.", "b": "Dobutamina.", "c": "Milrinona.", "d": "Adrenalina.", "e": "Noradrenalina."}, "answer": "c", "rationale": "Milrinona (e anrinona) aumentam o inotropismo e causam vasodilatação (inodilatador) por inibição enzimática, sendo úteis em pacientes já betabloqueados ou com resistência a catecolaminas.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Farmacologia de suporte inotrópico.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Choque", "Inotrópicos", "Milrinona"]}', 103, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma lesão em ''tandem'' (duas ou mais lesões em sequência no mesmo vaso). Como o FFR se comporta neste cenário?", "options": {"a": "O FFR é invalidado.", "b": "As lesões interferem uma na outra, dificultando a interpretação isolada (gradiente de pressão medido é a soma das resistências).", "c": "O FFR sempre subestima a gravidade.", "d": "O FFR sempre superestima a gravidade.", "e": "Basta somar as duas lesões no olho."}, "answer": "b", "rationale": "Lesões em tandem são um desafio para o FFR, pois a resistência de uma afeta o fluxo através da outra, o que pode mascarar o impacto real de cada lesão individualmente.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Limitação técnica do FFR.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "FFR", "Tandem", "Hemodinâmica"]}', 104, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de mortalidade extra-hospitalar súbita nos primeiros 60 minutos de um infarto agudo do miocárdio?", "options": {"a": "Choque cardiogênico.", "b": "Fibrilação Ventricular secundária a desequilíbrio metabólico e instabilidade elétrica.", "c": "Ruptura de ventrículo.", "d": "Insuficiência renal.", "e": "DPOC."}, "answer": "b", "rationale": "A FV primária é a grande vilã da morte súbita precoce no infarto (fase 1a da arritmia isquêmica). Por isso o treinamento em RCP e o uso de DEA são fundamentais.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causa de morte pré-hospitalar.", "c": "Incorreta. Ocorre mais tardiamente (dias).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Morte Súbita", "IAM", "Arritmias"]}', 105, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente tabagista pesado apresenta dor torácica recorrente ao exercício físico. O teste ergométrico revela infra de ST de 2 mm em V4-V6 que surge nos primeiros 3 minutos de esforço e demora 10 minutos para recuperar após o repouso. Esse achado sugere:", "options": {"a": "Repolarização precoce benigna.", "b": "Isquemia de alto risco (reposta precoce e recuperação lenta).", "c": "Falso positivo.", "d": "Saturação normal.", "e": "Angina estável de baixo risco."}, "answer": "b", "rationale": "Alterações precoces no teste de esforço e persistência das mesmas no repouso são sinais de gravidade e indicam anatomia coronariana complexa (estratificação invasiva precoce).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Critérios de gravidade no TE.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Ergometria", "SCA", "Risco"]}', 106, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal indicação para o uso de Ivabradina em um paciente com coronariopatia crônica e insuficiência cardíaca (FE < 35%)?", "options": {"a": "Substituir o betabloqueador.", "b": "Reduzir a frequência cardíaca em pacientes with ritmo sinusal and FC > 70 bpm que já estão em dose máxima tolerada de betabloqueador.", "c": "Tratar fibrilação atrial.", "d": "Aumentar a pressão arterial.", "e": "Reduzir o açúcar no sangue."}, "answer": "b", "rationale": "A Ivabradina age inibindo a corrente If do nó sinusal, reduzindo a FC sem afetar o inotropismo ou a PA, sendo útil na IC compensada com FC elevada residual.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Indicação específica baseada no estudo SHIFT.", "c": "Incorreta. Não funciona em FA (precisa de ritmo sinusal).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Ivabradina", "IC", "Frequência Cardíaca"]}', 107, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A imagem de ''delta'' ou de ''infra de ST em v1 com supra em v7-v9'' em um paciente com dor torácica é sugestiva de:", "options": {"a": "Normalidade.", "b": "Infarto de Ventrículo Direito.", "c": "Infarto Dorsal (Posterior) isolado.", "d": "Hipocalemia.", "e": "Pericardite."}, "answer": "c", "rationale": "As derivações posteriores confirmam a parede posterior do VE.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Diagnóstico por ECG expandido.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "ECG", "Infarto Posterior", "SCA"]}', 108, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O ''sinal de Levine'' na semiologia cardiológica refere-se a:", "options": {"a": "O paciente descreve a dor torácica com o punho fechado pressionado contra o esterno.", "b": "Diferença de pulso entre os braços.", "c": "Sopro umbilical.", "d": "Pulsão jugular.", "e": "Dor ao toque do tórax."}, "answer": "a", "rationale": "É um sinal clássico de dor isquêmica profunda.", "option_rationales": {"a": "Correta. Sinal semiológico visual.", "b": "Incorreta. Sugere dissecção de aorta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Sugere dor osteomuscular."}, "difficulty": "facil", "tags": ["Cardiologia", "Semiologia", "Levine", "Angina"]}', 109, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual dos seguintes parâmetros é considerado o melhor marcador bioquímico para o diagnóstico de reinfarto ou extensão do infarto nos primeiros dias após o evento agudo inicial?", "options": {"a": "Troponina ultrassensível.", "b": "CK-MB massa (por ter meia-vida curta e retornar ao valor basal em 48-72h).", "c": "Glicose.", "d": "LDH.", "e": "PCR."}, "answer": "b", "rationale": "Embora a troponina seja o padrão-ouro para o diagnóstico inicial, ela permanece elevada por 1 a 2 semanas. A CK-MB sobe e desce rápido, permitindo identificar um novo pico se houver re-isquemia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Uso prático da CK-MB.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Biomarcadores", "CK-MB", "Reinfarto"]}', 110, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Em um paciente com IAM inferior e supra de ST associado em V3 e V4, a diferenciação entre infarto de VD e infarto de parede anterior (espelho) pode ser feita por:", "options": {"a": "Dosagem de potássio.", "b": "ECG com derivações direitas (V3R/V4R).", "c": "Exame de urina.", "d": "Frequência respiratória.", "e": "Tomografia de abdome."}, "answer": "b", "rationale": "Derivações direitas confirmam VD.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Regra de ouro no infarto inferior.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "ECG", "Infarto de VD", "SCA"]}', 111, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente mostra uma oclusão total crônica (CTO) de ACD. O paciente tem boa circulação colateral da rede esquerda para a direita. Qual a recomendação para revascularização desta CTO, sendo o paciente assintomático?", "options": {"a": "Tentar abrir a qualquer custo.", "b": "Tratamento clínico otimizado (não há evidência de benefício em abrir CTOs em assintomáticos com boa colateral).", "c": "Realizar fibrinólise venosa.", "d": "Encaminhar para cirurgia de urgência.", "e": "Indicar apenas aspirina em dose tripla."}, "answer": "b", "rationale": "O tratamento de CTOs exige técnicas complexas e tem risco maior de complicações. Em assintomáticos, a evidência favorece o manejo clínico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta baseada no custo-benefício e evidência.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "CTO", "SCA", "Decisão"]}', 112, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "O uso de nitratos na fase aguda da SCA visa:", "options": {"a": "Desobstruir a artéria trombosada.", "b": "Reduzir o consumo de oxigênio miocárdico (por redução da pré-carga) e aliviar o vasoespasmo, reduzindo a dor.", "c": "Matar bactérias coronárias.", "d": "Aumentar a força de contração do coração.", "e": "Impedir o AVC."}, "answer": "b", "rationale": "Nitratos são vasodilatadores venosos (predominante) e arteriais, melhorando a oferta/demanda.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Alvo terapêutico fundamental.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Nitratos", "SCA"]}', 113, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No contexto da SCA, qual a principal indicação para o uso de anticoagulantes (heparina) junto com a antiagregação?", "options": {"a": "Aumentar a dor.", "b": "Prevenir a formação de trombos vermelhos (fibrina) e estabilizar o trombo branco (plaquetário) já formado.", "c": "Controlar o nível de açúcar.", "d": "Aumentar a pressão arterial.", "e": "Curar a pneumonia."}, "answer": "b", "rationale": "A cascata da coagulação é ativada após a ruptura da placa e agregação plaquetária. A heparina é essencial para evitar o crescimento do trombo.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Papel fisiopatológico da anticoagulação.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "Heparina", "SCA"]}', 114, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de ''não re-fluxo'' (no-reflow) após a abertura mecânica bem-sucedida de uma artéria coronária ocluída durante a ICP primária?", "options": {"a": "Vasoespasmo difuso.", "b": "Microembolização de detritos da placa e trombo para a microcirculação capilar.", "c": "Falta de soro no paciente.", "d": "Uso de stent muito pequeno.", "e": "Taquicardia atrial."}, "answer": "b", "rationale": "O no-reflow decorre de edema e obstrução microvascular, impedindo que o sangue atinja o tecido mesmo com a artéria principal aberta.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fenômeno de microcirculação pós-reperfusão.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "No-Reflow", "Hemodinâmica", "SCA"]}', 115, 'draft');
